type contentNodeShifter struct {
	numLanguages int
}

func (s *contentNodeShifter) LangIndex(n contentNodeI) int {
	switch v := n.(type) {
	case *pageState:
		site := v.s
		if v.m == nil || site == nil || site.language == nil {
			panic(fmt.Sprintf("missing language data for %T", n))
		}
		idx := site.languagei
		if idx < 0 || idx >= s.numLanguages {
			panic(fmt.Sprintf("invalid language index %d", idx))
		}
		return idx
	case *resourceSource:
		if v.r != nil && v.isPage() {
			ps := v.r.(*pageState)
			site := ps.s
			if ps.m == nil || site == nil || site.language == nil {
				panic(fmt.Sprintf("missing language data for %T", n))
			}
			idx := site.languagei
			if idx < 0 || idx >= s.numLanguages {
				panic(fmt.Sprintf("invalid language index %d", idx))
			}
			return idx
		}
		meta := v.fi.Meta()
		idx := meta.LangIndex
		if idx < 0 || idx >= s.numLanguages {
			panic(fmt.Sprintf("invalid language index %d for %q", idx, meta.Lang))
		}
		return idx
	default:
		panic(fmt.Sprintf("unknown type %T", n))
	}
}

func (s *contentNodeShifter) Delete(n contentNodeI, dimension doctree.Dimension) (bool, bool) {
	lidx := dimension[0]
	switch v := n.(type) {
	case contentNodeIs:
		resource.MarkStale(v[lidx])
		wasDeleted := v[lidx] != nil
		v[lidx] = nil
		isEmpty := true
		for _, vv := range v {
			if vv != nil {
				isEmpty = false
				break
			}
		}
		return wasDeleted, isEmpty
	case resourceSources:
		resource.MarkStale(v[lidx])
		wasDeleted := v[lidx] != nil
		v[lidx] = nil
		isEmpty := true
		for _, vv := range v {
			if vv != nil {
				isEmpty = false
				break
			}
		}
		return wasDeleted, isEmpty
	case *resourceSource:
		if lidx != s.LangIndex(v) {
			return false, false
		}
		resource.MarkStale(v)
		return true, true
	case *pageState:
		if lidx != s.LangIndex(v) {
			return false, false
		}
		resource.MarkStale(v)
		return true, true
	default:
		panic(fmt.Sprintf("unknown type %T", n))
	}
}

func (s *contentNodeShifter) Shift(n contentNodeI, dimension doctree.Dimension, exact bool) (contentNodeI, bool, doctree.DimensionFlag) {
	lidx := dimension[0]
	// How accurate is the match.
	accuracy := doctree.DimensionLanguage
	switch v := n.(type) {
	case contentNodeIs:
		if len(v) == 0 {
			panic("empty contentNodeIs")
		}
		vv := v[lidx]
		if vv != nil {
			return vv, true, accuracy
		}
		return nil, false, 0
	case resourceSources:
		vv := v[lidx]
		if vv != nil {
			return vv, true, doctree.DimensionLanguage
		}
		if exact {
			return nil, false, 0
		}
		// For non content resources, pick the first match.
		for _, vv := range v {
			if vv != nil {
				if vv.isPage() {
					return nil, false, 0
				}
				return vv, true, 0
			}
		}
	case *resourceSource:
		if s.LangIndex(v) == lidx {
			return v, true, doctree.DimensionLanguage
		}
		if !v.isPage() && !exact {
			return v, true, 0
		}
	case *pageState:
		if s.LangIndex(v) == lidx {
			return n, true, doctree.DimensionLanguage
		}
	default:
		panic(fmt.Sprintf("unknown type %T", n))
	}
	return nil, false, 0
}

func (s *contentNodeShifter) ForEeachInDimension(n contentNodeI, d int, f func(contentNodeI) bool) {
	if d != doctree.DimensionLanguage.Index() {
		panic("only language dimension supported")
	}

	switch vv := n.(type) {
	case contentNodeIs:
		for _, v := range vv {
			if v != nil {
				if f(v) {
					return
				}
			}
		}
	default:
		f(vv)
	}
}

